//#region src/datamitsu-config/utils.ts
function safeJsonParse(content) {
  try {
    return JSON.parse(content || "{}");
  } catch {
    return {};
  }
}
function withTrailingNewline(content) {
  return content.replace(/\n*$/, "\n");
}
